200	// placementFailureError reduces a failed `entire repo view --json` to the line
201	// the host CLI actually said. The runner's wrap carries debug framing — an
202	// argv echo plus the host's "Using context '…'." login banner — that a human
203	// reading connect's failure never needs. Drop the banner, then let
204	// providerdetail.Summary keep the host's Error:-marked or first stderr line.
205	func placementFailureError(runErr error, stderr []byte) error {
206		var kept []string
207		for _, line := range strings.Split(string(stderr), "\n") {
208			line = strings.TrimSpace(line)
209			if line == "" || strings.HasPrefix(line, "Using context ") {
210				continue
211			}
212			kept = append(kept, line)
213		}
214		if summary := providerdetail.Summary(strings.Join(kept, "\n")); summary != "" {
215			return errors.New(summary)
216		}
217		// Nothing usable on stderr: name the command and the cause under the
218		// runner's argv echo (exit status, or a missing host CLI).
219		cause := runErr
220		if unwrapped := errors.Unwrap(runErr); unwrapped != nil {
221			cause = unwrapped
222		}
223		return fmt.Errorf("`entire repo view --json`: %v", cause)
