230	func checkHostCLIVersion(ctx context.Context, runner CommandRunner, repoDir, min string) error {
231		if min == "" {
232			return nil
233		}
234		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "version")
235		if err != nil {
236			return nil
237		}
238		// First line is "Entire CLI <version>", on some builds with a trailing
239		// "(<commit>)". Take the first field that parses as semver, not a fixed
240		// position, so a build suffix cannot fail-open the gate.
241		line, _, _ := strings.Cut(strings.TrimSpace(string(stdout)), "\n")
242		got := ""
243		for _, field := range strings.Fields(line) {
244			if v := "v" + strings.TrimPrefix(field, "v"); semver.IsValid(v) {
245				got = v
246				break
247			}
248		}
249		if got == "" {
250			return nil
251		}
252		// Compare the release core only: a prerelease or pseudo-version of min
253		// (nightly, git describe) ranks below min in full semver order yet may
254		// already ship repo view — those builds pass and repo view stays the
255		// authority.
256		core := strings.TrimSuffix(got, semver.Build(got))
257		core = strings.TrimSuffix(core, semver.Prerelease(core))
258		if semver.Compare(core, "v"+min) >= 0 {
259			return nil
260		}
261		return fmt.Errorf("entire CLI %s does not support `entire repo view` (needs %s or newer); upgrade the entire CLI and re-run connect", strings.TrimPrefix(got, "v"), min)
